using System.Security.Cryptography; using System.Text; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.DataProtection; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.Integrations; using OrcaFacil.Application.Security; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Settings.Webhooks;
[Authorize(Policy="Permission:"+PermissionCodes.WebhooksView)] public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current,IAuthorizationService authorization,IDataProtectionProvider protection,IAuditService audit,IWebHostEnvironment environment):PageModel { [BindProperty] public string Name{get;set;}="";[BindProperty] public string Url{get;set;}="";[BindProperty] public string[] Events{get;set;}=[];public IReadOnlyList<WebhookEndpoint> Items{get;private set;}=[];public string? CreatedSecret=>TempData["WebhookSecret"] as string;public async Task<IActionResult> OnGetAsync(CancellationToken ct){if(!current.AccountId.HasValue)return Forbid();Items=await db.WebhookEndpoints.AsNoTracking().Where(x=>x.AccountId==current.AccountId&&!x.IsDeleted).OrderBy(x=>x.Name).ToListAsync(ct);return Page();}public async Task<IActionResult> OnPostCreateAsync(CancellationToken ct){if(!current.AccountId.HasValue||!(await authorization.AuthorizeAsync(User,"Permission:"+PermissionCodes.WebhooksManage)).Succeeded)return Forbid();if(!Uri.TryCreate(Url,UriKind.Absolute,out var uri)||uri.Scheme!=(environment.IsProduction()?"https":uri.Scheme)||uri.Scheme is not ("http" or "https")){ModelState.AddModelError(nameof(Url),environment.IsProduction()?"Em produção, use uma URL HTTPS válida.":"Use uma URL HTTP ou HTTPS válida.");return await OnGetAsync(ct);}if(Events.Length==0||Events.Any(x=>!WebhookEventTypes.Allowed.Contains(x))){ModelState.AddModelError(nameof(Events),"Selecione eventos permitidos.");return await OnGetAsync(ct);}var secret=Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant();var x=new WebhookEndpoint{AccountId=current.AccountId.Value,Name=Name.Trim(),Url=uri.ToString(),EventTypes=string.Join(',',Events.Distinct()),SecretHash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(secret))).ToLowerInvariant(),ProtectedSecret=protection.CreateProtector("OrcaFacil.Webhooks.Secret.v1").Protect(secret)};db.Add(x);await db.SaveChangesAsync(ct);await audit.RegisterAsync(current.UserId,"webhook.created",nameof(WebhookEndpoint),x.Id.ToString(),null,new{x.Name,x.Url,x.EventTypes},null,ct,current.AccountId);TempData["WebhookSecret"]=secret;return RedirectToPage();}public async Task<IActionResult> OnPostToggleAsync(Guid id,CancellationToken ct){if(!current.AccountId.HasValue||!(await authorization.AuthorizeAsync(User,"Permission:"+PermissionCodes.WebhooksManage)).Succeeded)return Forbid();var x=await db.WebhookEndpoints.SingleOrDefaultAsync(x=>x.Id==id&&x.AccountId==current.AccountId&&!x.IsDeleted,ct);if(x is null)return NotFound();x.IsActive=!x.IsActive;await db.SaveChangesAsync(ct);return RedirectToPage();}}
